89	/*
90	 * send_icmp6_ndisc_adv
91	 * @ctx:	socket buffer
92	 * @nh_off:	offset to the IPv6 header
93	 * @mac:	device mac address
94	 * @to_router:	ndisc is sent to router, otherwise ndisc is sent to an endpoint.
95	 *
96	 * Send an ICMPv6 nadv reply in return to an ICMPv6 ndisc.
97	 */
98	static __always_inline int
99	send_icmp6_ndisc_adv(struct __ctx_buff *ctx, int nh_off,
100			     const union macaddr *mac, bool to_router)
101	{
102		struct icmp6hdr icmp6hdr __align_stack_8 = {}, icmp6hdr_old __align_stack_8;
103		__u8 opts[8], opts_old[8];
104		const int csum_off = nh_off + ICMP6_CSUM_OFFSET;
105		__be32 sum;
106	
107		if (ctx_load_bytes(ctx, nh_off + sizeof(struct ipv6hdr), &icmp6hdr_old,
108				   sizeof(icmp6hdr_old)) < 0)
109			return DROP_INVALID;
110	
111		/* fill icmp6hdr */
112		icmp6hdr.icmp6_type = ICMP6_NA_MSG_TYPE;
113		icmp6hdr.icmp6_code = 0;
114		icmp6hdr.icmp6_cksum = icmp6hdr_old.icmp6_cksum;
115		icmp6hdr.icmp6_dataun.un_data32[0] = 0;
116	
117		if (to_router) {
118			icmp6hdr.icmp6_router = 1;
119			icmp6hdr.icmp6_solicited = 1;
120			icmp6hdr.icmp6_override = 0;
121		} else {
122			icmp6hdr.icmp6_router = 0;
123			icmp6hdr.icmp6_solicited = 1;
124			icmp6hdr.icmp6_override = 1;
125		}
126	
127		if (ctx_store_bytes(ctx, nh_off + sizeof(struct ipv6hdr), &icmp6hdr,
128				    sizeof(icmp6hdr), 0) < 0)
129			return DROP_WRITE_ERROR;
130	
131		/* fixup checksums */
132		sum = csum_diff(&icmp6hdr_old, sizeof(icmp6hdr_old),
133				&icmp6hdr, sizeof(icmp6hdr), 0);
134		if (l4_csum_replace(ctx, csum_off, 0, sum, BPF_F_PSEUDO_HDR) < 0)
135			return DROP_CSUM_L4;
136	
137		/* get old options */
138		if (ctx_load_bytes(ctx, nh_off + ICMP6_ND_OPTS, opts_old, sizeof(opts_old)) < 0)
139			return DROP_INVALID;
140	
141		opts[0] = 2;
142		opts[1] = 1;
143		opts[2] = mac->addr[0];
144		opts[3] = mac->addr[1];
145		opts[4] = mac->addr[2];
146		opts[5] = mac->addr[3];
147		opts[6] = mac->addr[4];
148		opts[7] = mac->addr[5];
149	
150		/* store ND_OPT_TARGET_LL_ADDR option */
151		if (ctx_store_bytes(ctx, nh_off + ICMP6_ND_OPTS, opts, sizeof(opts), 0) < 0)
152			return DROP_WRITE_ERROR;
153	
154		/* fixup checksum */
155		sum = csum_diff(opts_old, sizeof(opts_old), opts, sizeof(opts), 0);
156		if (l4_csum_replace(ctx, csum_off, 0, sum, BPF_F_PSEUDO_HDR) < 0)
157			return DROP_CSUM_L4;
158	
159		return icmp6_send_reply(ctx, nh_off);
160	}
