static __always_inline int
icmp6_ndisc_adv_addopt(struct __ctx_buff *ctx)
{
	struct ipv6hdr *ip6;
	void *data, *data_end;
	__u64 *opt;

	if (ctx_change_tail(ctx, (__u32)(ctx_full_len(ctx) + ICMP6_ND_OPT_LEN), 0) < 0)
		return DROP_INVALID;

	if (!revalidate_data(ctx, &data, &data_end, &ip6))
		return DROP_INVALID;

	ip6->payload_len = bpf_htons(bpf_ntohs(ip6->payload_len) +
				     ICMP6_ND_OPT_LEN);

	/* Zero the freshly-added option bytes so that the incremental checksum
	 * computed against the "old" options stays additive.
