96	 * link-layer address option, updating the IPv6 payload length accordingly.
97	 * This is required when the incoming Neighbour Solicitation does not carry a
98	 * source link-layer address option, in which case there is no existing option
99	 * we can overwrite.
100	 */
101	static __always_inline int
102	icmp6_ndisc_adv_addopt(struct __ctx_buff *ctx)
103	{
104		struct ipv6hdr *ip6;
105		void *data, *data_end;
106		__u64 *opt;
107	
108		if (ctx_change_tail(ctx, (__u32)(ctx_full_len(ctx) + ICMP6_ND_OPT_LEN), 0) < 0)
109			return DROP_INVALID;
110	
111		if (!revalidate_data(ctx, &data, &data_end, &ip6))
112			return DROP_INVALID;
113	
114		ip6->payload_len = bpf_htons(bpf_ntohs(ip6->payload_len) +
115					     ICMP6_ND_OPT_LEN);
116	
117		/* Zero the freshly-added option bytes so that the incremental checksum
118		 * computed against the "old" options stays additive.
119		 */
120		opt = (__u64 *)((void *)(ip6 + 1) + sizeof(struct icmp6hdr) +
121				sizeof(union v6addr));
